curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -d '{
    "query": "
      {
        teams(name: \"Web\") {
          nodes {
            id
            name
          }
        }
        users(filter: { search: { _eq: \"Maya Chen\" } }) {
          nodes {
            id
            name
            displayName
          }
        }
      }
    '
  }'
